section.sourcecode:
/* pは、クラシックキューで発生している遅延に応じて、
 *  任意のL4S AQMが計算する内部変数です。
 * bit13は、TRILL-ECNフィールドの最下位ビットです。
 */

% TRILLの中継で
if (bit13 == 0 ) {
      % クラシックキュー
      if (p > max(random(), random()) )
         mark(CCE)                         % 確率: p^2

} else {
      % L4Sキュー
      if (p > random() ) {
         if (p > random() )
            mark(CCE)                      % 確率: p^2
         else
            mark(NCCE)                     % 確率: p - p^2
      }
}
